package dev.gbppimentel.snapcompanion;
import org.junit.Test;import static org.junit.Assert.*;
public class ControllerButtonsTest {
 @Test public void tracksPhysicalEdgesWithoutInventingKeyboardPresses(){var b=new ControllerButtons();assertTrue(b.accept(1,304,1,1000));assertTrue(b.down().get("A"));assertEquals(Long.valueOf(1000),b.pulses().get("A"));assertFalse(b.accept(1,304,2,1050));assertTrue(b.accept(1,304,0,1100));assertFalse(b.down().get("A"));assertEquals(Long.valueOf(1000),b.pulses().get("A"));assertFalse(b.accept(1,30,1,1200));assertFalse(b.down().containsKey("KEY_A"));}
 @Test public void hatsTriggersAndStickClicksHaveIndependentStates(){var b=new ControllerButtons();b.accept(3,16,-1,1000);assertTrue(b.down().get("LEFT"));assertFalse(b.down().get("RIGHT"));b.accept(3,16,1,1100);assertFalse(b.down().get("LEFT"));assertTrue(b.down().get("RIGHT"));b.accept(3,10,32767,1200);b.accept(1,317,1,1200);assertTrue(b.down().get("L2"));assertTrue(b.down().get("L3"));b.accept(3,10,0,1300);assertFalse(b.down().get("L2"));assertTrue(b.down().get("L3"));}
 @Test public void droppedInputClearsDownStatesAndPulses(){var b=new ControllerButtons();b.accept(1,305,1,1000);assertTrue(b.accept(0,3,0,1100));assertTrue(b.down().isEmpty());assertTrue(b.pulses().isEmpty());}
 @Test public void onlyBuiltInNamesQualifyAndCallersCannotMutateState(){assertTrue(ControllerButtons.builtInScore("Odin Controller")>0);assertTrue(ControllerButtons.builtInScore("AYN Gamepad")>0);assertEquals(0,ControllerButtons.builtInScore("USB Keyboard"));assertEquals(0,ControllerButtons.builtInScore("Odin Keyboard"));assertEquals(0,ControllerButtons.builtInScore("Bluetooth Gamepad"));var b=new ControllerButtons();b.accept(1,307,1,1000);b.down().clear();assertTrue(b.down().get("X"));}
 @Test public void analogueAxesUseSignedThorMappingClampAndDeadZone(){var b=new ControllerButtons();b.accept(3,0,32767,1000);b.accept(3,1,-32768,1000);b.accept(3,2,16384,1000);b.accept(3,5,400,1000);assertEquals(1.0,b.axes().get("lx"),0);assertEquals(-1.0,b.axes().get("ly"),0);assertEquals(.5,b.axes().get("rx"),.01);assertEquals(0.0,b.axes().get("ry"),0);b.axes().clear();assertEquals(4,b.axes().size());b.accept(3,0,0,1100);assertEquals(0.0,b.axes().get("lx"),0);}
 @Test public void droppedInputClearsAnaloguePositions(){var b=new ControllerButtons();b.accept(3,0,20000,1000);b.accept(0,3,0,1100);assertTrue(b.axes().isEmpty());}
 @Test public void droppedPacketIsIgnoredUntilSynReportAndDoesNotInventHeldButtons(){var b=new ControllerButtons();b.accept(1,304,1,1000);b.accept(0,3,0,1100);assertFalse(b.accept(1,305,1,1200));assertFalse(b.accept(3,0,30000,1200));assertTrue(b.down().isEmpty());assertTrue(b.axes().isEmpty());b.accept(0,0,0,1300);assertTrue(b.accept(1,305,1,1400));assertTrue(b.down().get("B"));assertFalse(b.down().containsKey("A"));}
}
